x = 5
if x > 3:
    print('Yes')
else:
    print('No')

x = 10
if x < 5:
    print('Small')
elif x > 8:
    print('Medium')
else:
    print('Large')

x = 4
if x == 4:
    print('Four')
if x != 4:
    print('Not Four')

x = -1
if x > 0:
    print('Positive')
elif x < 0:
    print('Negative')
else:
    print('Zero')

x = [1, 2, 3]
if len(x) == 3:
    print('Three')
else:
    print('Not Three')

value = 10
if value % 2 == 0:
    print('Even')
else:
    print('Odd')

num = 0
if num:
    print('True')
else:
    print('False')
